static void аты_кесте(unsigned x_координатасы,unsigned Y_түймешігі_координата,const char *жол_деректер,unsigned 전경색,unsigned 배경색){while(*жол_деректер){unsigned таңба_коды=(unsigned char)*жол_деректер++, 남은수=0;if(таңба_коды>=0xc0){남은수=таңба_коды<0xe0?1:таңба_коды<0xf0?2:3;таңба_коды&=(1u<<(6-남은수))-1;while(남은수--&&*жол_деректер)таңба_коды=(таңба_коды<<6)|((unsigned char)*жол_деректер++&63);}Терминал_глиф(x_координатасы,Y_түймешігі_координата,таңба_коды,전경색,배경색);x_координатасы+=кеңейтілген_таңба(таңба_коды)*8;}}
