static void 장면그리기(void){
    if(!үстелдік_Көрініс)return;사각영역(0,0,보드화면너비(),보드화면높이(),0x302018);사각영역(0,0,보드화면너비(),32,0x403127);
    사각영역(6,4,136,24,0x905020);аты_кесте(14,8,"+ New terminal",0xffffff,0x905020);
    for(int 순번=0;순번<4;순번++)if(창들[순번].살아있음){unsigned таңба_коды=Фокус==순번?0x905020:0x604438;사각영역(154+순번*112,4,106,24,таңба_коды);аты_кесте(160+순번*112,8,"Terminal",0xffffff,таңба_коды);char жол_деректер[2]={(char)('1'+순번),0};аты_кесте(232+순번*112,8,жол_деректер,0xffffff,таңба_коды);}
    if(!항목수)аты_кесте(140,210,"Click + New terminal to start",0xede9df,0x302018);
    for(int 순번=0;순번<항목수;순번++)실행틀(рет_мән[순번]);화면다시그림(Фокус);Терминал_енгізу=&창들[출력결과];
}
static void 영역그리기(int 가로,int Тік_лауазым,int 폭,int ұзындық_мән){
    if(!үстелдік_Көрініс||!보드그림범위(&가로,&Тік_лауазым,&폭,&ұзындық_мән))return;
    for(int Жол=Тік_лауазым;Жол<Тік_лауазым+ұзындық_мән;Жол+=32){
        int 띠높이=Тік_лауазым+ұзындық_мән-Жол;if(띠높이>32)띠높이=32;
        if(Тақта_басы_сызба(가로,Жол,폭,띠높이)){장면그리기();Тақта_соңы_сызба();}
    }
}
static void 다시그리기(void){영역그리기(0,0,보드화면너비(),보드화면높이());}
/* 서로 겹치지 않는 새 Терезе 영역과 이전 자리의 네 띠를 복구한다. */
static void 창자리그리기(int 가로,int Тік_лауазым,int 폭,int ұзындық_мән,Терминал_d413d4bc *Терезе){
    int 왼쪽=가로>(int)Терезе->x_координатасы?가로:(int)Терезе->x_координатасы;
    int 위쪽=Тік_лауазым>(int)Терезе->Y_түймешігі_координата?Тік_лауазым:(int)Терезе->Y_түймешігі_координата;
    int 오른쪽=가로+폭<(int)(Терезе->x_координатасы+Терезе->너비)?가로+폭:(int)(Терезе->x_координатасы+Терезе->너비);
    int 아래쪽=Тік_лауазым+ұзындық_мән<(int)(Терезе->Y_түймешігі_координата+Терезе->높이)?Тік_лауазым+ұзындық_мән:(int)(Терезе->Y_түймешігі_координата+Терезе->높이);
    영역그리기(Терезе->x_координатасы,Терезе->Y_түймешігі_координата,Терезе->너비,Терезе->높이);
    if(왼쪽>=오른쪽||위쪽>=아래쪽){영역그리기(가로,Тік_лауазым,폭,ұзындық_мән);return;}
    영역그리기(가로,Тік_лауазым,폭,위쪽-Тік_лауазым);
    영역그리기(가로,아래쪽,폭,Тік_лауазым+ұзындық_мән-아래쪽);
    영역그리기(가로,위쪽,왼쪽-가로,아래쪽-위쪽);
    영역그리기(오른쪽,위쪽,가로+폭-오른쪽,아래쪽-위쪽);
}
